import { calculateAcademicProfile, calculateVendingForecast, estimateLuxTransmission, generateSampleSalesCsv, getRouteDistanceDisplay, compareTrafficRoutes, buildDepartureTimeline, parseOperationalCsv, simulateSwarmRouting, validateOperationalCsvFile, getShockReportSummary, isShockActive, isShockReportReady, simulateVeloRouteShock, type FleetEndpoint, type LuxFrameSample, type ShockInputs } from "@/lib/operations";
